INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3002, 'fr-FR', 'name', 'Logo de l\'application', 'reviewed', SHA2('应用LOGO', 256), NULL, NULL, 1, CURRENT_TIMESTAMP, 1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3003, 'fr-FR', 'name', 'Politique de confidentialité', 'reviewed', SHA2('隐私协议', 256), NULL, NULL, 1, CURRENT_TIMESTAMP, 1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3003, 'fr-FR', 'value', '<h2>Politique de confidentialité</h2><p>Merci d\'utiliser cette application. Nous valorisons et protégeons vos informations personnelles et les traitons uniquement dans la mesure nécessaire pour fournir la connexion au compte, les fonctionnalités de l\'application et le service client.</p><h3>I. Utilisation des informations</h3><p>Nous utilisons vos informations conformément aux lois applicables et à la présente politique, et ne les utiliserons pas à des fins indépendantes.</p><h3>II. Vos droits</h3><p>Vous pouvez accéder, corriger ou supprimer vos informations personnelles conformément à la loi, ou nous contacter via les canaux publiés dans l\'application.</p>', 'reviewed', SHA2('<h2>隐私政策</h2><p>感谢您使用本应用。我们重视并保护您的个人信息，仅在提供账号登录、应用功能和客户服务所必需的范围内处理相关信息。</p><h3>一、信息使用</h3><p>我们会按照法律法规和本协议约定使用您的信息，不会将其用于无关目的。</p><h3>二、您的权利</h3><p>您可以依法查询、更正、删除个人信息，或通过应用内公布的渠道联系我们。</p>', 256), NULL, NULL, 1, CURRENT_TIMESTAMP, 1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3004, 'fr-FR', 'name', 'Conditions d\'utilisation', 'reviewed', SHA2('服务条款', 256), NULL, NULL, 1, CURRENT_TIMESTAMP, 1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0);
INSERT IGNORE INTO `base_config_translation` (`config_id`, `locale`, `field`, `text`, `translation_status`, `source_hash`, `translation_provider`, `translated_at`, `reviewed_by`, `reviewed_at`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3004, 'fr-FR', 'value', '<h2>Conditions d\'utilisation</h2><p>Bienvenue dans cette application. Veuillez lire et comprendre cet accord et les règles associées avant d\'utiliser l\'application. En utilisant les services de l\'application, vous acceptez de les respecter.</p><h3>I. Utilisation du service</h3><p>Veuillez utiliser chaque fonctionnalité légalement et conformément aux instructions sur la page. Vous ne devez pas utiliser cette application pour des activités illégales ou des activités qui portent atteinte aux droits d\'autrui.</p><h3>II. Modifications apportées à l\'accord</h3><p>Nous pouvons mettre à jour cet accord en fonction des changements dans les affaires et les lois et réglementations, et afficherons la version mise à jour dans l\'application.</p>', 'reviewed', SHA2('<h2>服务条款</h2><p>欢迎使用本应用。使用本应用前，请您阅读并理解本协议。您开始使用应用服务，即表示同意遵守本协议及相关规则。</p><h3>一、服务使用</h3><p>请您依法、合规并按照页面提示使用各项功能，不得利用本应用从事违法或损害他人权益的活动。</p><h3>二、协议变更</h3><p>我们会根据业务和法律法规变化更新本协议，并在应用内向您展示更新后的内容。</p>', 256), NULL, NULL, 1, CURRENT_TIMESTAMP, 1, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0);
